const locationSearch = String(wh.location || '').toLowerCase();
const sd = $getWorkflowStaticData('global');

// The old shortlist-based record is still honoured; it is a subset of the new one.
const legacySeen = new Set((sd.hhSeenUrls && sd.hhSeenUrls[searchId]) || []);

const DAY_MS = 24 * 60 * 60 * 1000;
const now = Date.now();
sd.hhFetched = sd.hhFetched || {};
for (const [id, rec] of Object.entries(sd.hhFetched)) {
  if (!rec || typeof rec.at !== 'number' || now - rec.at > DAY_MS) delete sd.hhFetched[id];
}
const fetched = new Set((sd.hhFetched[searchId] && sd.hhFetched[searchId].slugs) || []);

function slugOf(link) {
  const m = String(link || '').match(/linkedin\.com\/in\/([^?#/]+)/i);
  if (!m) return '';
  let s = m[1];
  try { s = decodeURIComponent(s); } catch (e) {}
  return s.trim().toLowerCase();
}

function subdomainOf(link) {
  const m = String(link || '').match(/^https?:\/\/([a-z0-9-]+)\.linkedin\.com/i);
  return m ? m[1].toLowerCase() : '';
}

// Same definition `Map Candidate Fields` uses.
const isIraqSearch = ['iraq', 'baghdad', 'عراق', 'بغداد'].some((t) => locationSearch.includes(t));
const IRAQ_SEARCH_KEEP = new Set(['www', 'iq', 'sy']);

function foreignSubdomain(link) {
  if (!isIraqSearch) return false;
  const sub = subdomainOf(link);
  return /^[a-z]{2}$/.test(sub) && !IRAQ_SEARCH_KEEP.has(sub);
}

const inPhase2 = Boolean(sd.hhPhase2 && sd.hhPhase2[searchId]);
const tier = $('Resolve Search Tier').first().json || {};
const tierCap = Number(tier.maxEnrich);
const phase2Cap = inPhase2 ? Number(sd.hhPhase2[searchId].maxEnrich) : NaN;
const cap = inPhase2
  ? (phase2Cap > 0 ? phase2Cap : Infinity)
  : (tierCap > 0 ? tierCap : Infinity);
const spend = sd.hhSpend && sd.hhSpend[searchId];
const budgetCap = spend && inPhase2
  ? Math.max(1, Math.floor((Number(spend.ceiling) - Number(spend.spent || 0)) / 2))
  : Infinity;
const limit = Math.min(cap, budgetCap);
const costOf = (item) => (item.json && item.json.__ps === true ? 1 : 2);
let phase1Spent = spend ? Number(spend.spent || 0) : 0;

const out = [];
const taken = new Set();
for (const item of $input.all()) {
  const link = String(item.json.link || item.json.url || '').trim();
  if (!link) continue;
  const lower = link.toLowerCase();
  if (legacySeen.has(lower.split('?')[0]) || legacySeen.has(lower)) continue;
  const slug = slugOf(link);
  if (!slug) continue;
  if (fetched.has(slug) || taken.has(slug)) continue;
  if (foreignSubdomain(link)) continue;
  if (out.length >= limit) break;
  if (spend && !inPhase2) {
    if (phase1Spent + costOf(item) > Number(spend.ceiling) - 2) continue;
    phase1Spent += costOf(item);
  }
  taken.add(slug);
  out.push(item);
}

sd.hhFetched[searchId] = { at: now, slugs: [...fetched, ...taken] };
if (spend) spend.spent = Number(spend.spent || 0) + out.reduce((n, i) => n + costOf(i), 0);

// EMPTY RESULT (2026-10-02). n8n runs nothing after an empty list. A phase 1 whose
// every profile was dropped here ended with no completion (record `submitted`, the
// page spinning for 10 minutes); so did a phase 2, unless a late phase-1 loop-back
// happened to re-run the finalize nodes, which first re-sent the whole phase-1
// shortlist. Exec 2057 (a pinned smoke test whose phase 2 got back only profiles
// phase 1 had already fetched, plus one on a foreign subdomain) shows the stall on
// the live engine. Instead ONE control item goes on, and Nothing To Enrich? routes
// it around the enrichment loop, so nothing more is paid for:
//   - phase 2: Phase 2 Found Nothing? -> Finalize Phase 2 Send, which reports the
//     phase-1 totals exactly as it does when phase 2 finds nobody new;
//   - phase 1: Phase 2 Found Nothing? -> Prepare Complete Search, a 'no candidates'
//     completion (the way Merge Serp Results closes a phase 1 with no profile).
if (!out.length) {
  const received = $input.all().length;
  const close = { __completeOnly: true, __nothingToEnrich: true, __phase2: inPhase2, received };
  if (!inPhase2) {
    const foreign = $input.all().filter((i) => foreignSubdomain(String(i.json.link || i.json.url || '').trim())).length;
    close.searchFailed = false;
    close.errorMessage = foreign === received
      ? 'No candidates found in Iraq: all ' + received + ' LinkedIn profile(s) the search returned are on LinkedIn sites of other countries.'
      : 'No candidates found: none of the ' + received + ' LinkedIn profile(s) the search returned could be evaluated.';
  }
  return [{ json: close }];
}
return out;

const wh = $('Webhook').first().json.body || {};
const searchId = String(wh.searchId || '');
const locationSearch = String(wh.location || '').toLowerCase();
const sd = $getWorkflowStaticData('global');
// Finalize ONCE per phase per search (2026-10): see Finalize Top N Send. A repeat run
// here found the pool gone and reported the phase-1 count as the total - 21 repeat
// completions in the 9 saved runs, 18 of them lower than the one posted - and
// overwrote hhSendProgress on the way. It now returns before touching anything else.
sd.hhFinalized = sd.hhFinalized || {};
const hhFin = sd.hhFinalized[searchId] || (sd.hhFinalized[searchId] = {});
if (hhFin.p2) return [];
hhFin.p2 = true;
const tier = $('Resolve Search Tier').first().json || {};
const minTarget = Number(tier.minCount) || 40;
const pool = sd.hhCandidates && sd.hhCandidates[searchId] ? [...sd.hhCandidates[searchId]] : [];
const sentKeys = new Set((sd.hhSentKeys && sd.hhSentKeys[searchId]) || []);

const isIraqSearch =
  locationSearch.includes('iraq') ||
  locationSearch.includes('baghdad') ||
  locationSearch.includes('عراق') ||
  locationSearch.includes('بغداد');

const US_EXCLUDE = [
  'united states', 'u.s.', 'usa', 'america', 'california', 'texas', 'new york', 'florida', 'orange county',
];
const NON_IRAQ_EXCLUDE = [
  'iran', 'tehran', 'turkey', 'uae', 'dubai', 'saudi', 'jordan', 'kuwait', 'qatar', 'egypt',
];

function norm(s) {
  return String(s || '').toLowerCase();
}

function profileKey(j) {
  const url = String(j.linkedin_url || '').trim().toLowerCase().split('?')[0];
  if (url) return url;
  return `name:${String(j.name || '').trim().toLowerCase()}`;
}

function isBadLocation(j) {
  const loc = norm(j.location);
  if (!loc) return false;
  if (US_EXCLUDE.some((t) => loc.includes(t))) return true;
  if (NON_IRAQ_EXCLUDE.some((t) => loc.includes(t)) && !loc.includes('iraq') && loc !== 'iq') return true;
  return false;
}

function rankScore(j) {
  let score = Number(j.match_score) || 0;
  if (Number(j.location_priority) === 1) score += 8;
  if (locationSearch.includes('baghdad') && norm(j.location).includes('baghdad')) score += 5;
  return score;
}

const ranked = pool.map((j) => ({ ...j }));
ranked.sort((a, b) => rankScore(b) - rankScore(a));

let shortlist = ranked.filter((j) => (Number(j.match_score) || 0) >= 50);
if (shortlist.length === 0) shortlist = ranked.filter((j) => (Number(j.match_score) || 0) >= 45);
if (shortlist.length === 0) shortlist = ranked.filter((j) => (Number(j.match_score) || 0) >= 40);
if (shortlist.length === 0) shortlist = ranked;

if (isIraqSearch) {
  const cleaned = shortlist.filter((j) => !isBadLocation(j));
  if (cleaned.length > 0) shortlist = cleaned;
}

shortlist.sort((a, b) => rankScore(b) - rankScore(a));
// Only the SHORTFALL. Without this the second wave sends its whole shortlist ON
// TOP of what phase 1 already sent, and the recruiter is billed per candidate for
// people they never asked for: 13 + 20 when they asked for 20.
const phase1Sent = (sd.hhPhase1SentCount && sd.hhPhase1SentCount[searchId]) || 0;
const remaining = Math.max(0, minTarget - phase1Sent);
const toSend = shortlist.filter((j) => !sentKeys.has(profileKey(j))).slice(0, remaining);

if (sd.hhCandidates) delete sd.hhCandidates[searchId];
if (sd.hhExpansionActive) delete sd.hhExpansionActive[searchId];
if (sd.hhPhase2) delete sd.hhPhase2[searchId];

const phase1Count = (sd.hhPhase1SentCount && sd.hhPhase1SentCount[searchId]) || 0;
const totalAfter = phase1Count + toSend.length;

sd.hhSendProgress = sd.hhSendProgress || {};
sd.hhSendProgress[searchId] = {
  expected: toSend.length,
  sent: 0,
  phase: 2,
  phase1Count,
  minTarget,
  totalAfter,
};

if (toSend.length === 0) {
  return [
    {
      json: {
        searchId,
        searchComplete: true,
        __completeOnly: true,
        phase1Count,
        totalSent: phase1Count,
        minTarget,
        targetMet: phase1Count >= minTarget,
        expansionRan: true,
      },
    },
  ];
}

return toSend.map((j) => {
  const { location_priority, __skip, ...rest } = j;
  const key = profileKey(j);
  if (!sd.hhSentKeys) sd.hhSentKeys = {};
  if (!sd.hhSentKeys[searchId]) sd.hhSentKeys[searchId] = [];
  sd.hhSentKeys[searchId].push(key);
  return {
    json: {
      ...rest,
      __finalPhase: true,
      phase1Count,
      minTarget,
    },
  };
});

const raw = $input.first().json;
let txt = raw.text ?? raw.output ?? '';
if (typeof txt !== 'string') txt = JSON.stringify(txt);
txt = String(txt).replace(/^```(?:json)?/i, '').replace(/```$/i, '').trim();
let parsed = {};
try { parsed = JSON.parse(txt); } catch (e) {
  const m = txt.match(/\{[\s\S]*\}/);
  if (m) { try { parsed = JSON.parse(m[0]); } catch (e2) {} }
}
const wh = $('Webhook').first().json.body || {};
const position = String(parsed.position || wh.position || '').trim();
const location = String(parsed.location || wh.location || '').trim();
return [{ json: { position, location } }];

/**
 * Person Search Plan - should this search ask EnrichLayer Person Search first?
 *
 * Owner-approved design (2026-10-01, measured the same day: 10 of 10 profiles in Iraq,
 * 80-90% passed our evaluation against 43-58% on the Google path, and 0 of 20 overlapped
 * with what Google had found). Person Search returns profile LINKS only (3 credits per
 * result returned); they join the existing path in front of Filter New URLs, so dedupe,
 * the enrichment cap, the loop, the evaluation, sending and billing all stay as they are -
 * the one addition is the shared ceiling below, which Filter New URLs enforces.
 *
 *   - Iraq searches only (the same four location words Map Candidate Fields uses), with
 *     a plain-English title: the recruiter's own, or for an Arabic title its English
 *     translation (Apply Translation, the text Google's queries use; 2026-10-03).
 *   - It asks for as many links as the search wants (20 / 40). Google's phase 1 is skipped
 *     only when Person Search fills that number by itself; otherwise both run together.
 *   - It opens a spend record: the WHOLE search may use at most 120 (Tier 20) / 240
 *     (Tier 40) EnrichLayer credits. Filter New URLs enforces it in both phases.
 *   - CONFIG.orgAllowlist empty means EVERY organisation. Switched on for every organisation
 *     on 2026-10-03 (owner decision: few subscribers yet, so no allowlist).
 *
 * Any failure here falls back to the Google path exactly as it was. This node never throws.
 */
const CONFIG = {
  enabled: true, // on for every organisation since 2026-10-03 (owner decision: few subscribers yet)
  orgAllowlist: [], // empty = every organisation; otherwise only these organizationIds
  ceiling: { 20: 120, 40: 240 }, // EnrichLayer credits for the whole search
};
const DAY_MS = 24 * 60 * 60 * 1000;
// Same definition `Map Candidate Fields` uses.
const IRAQ_WORDS = ['iraq', 'baghdad', 'عراق', 'بغداد'];

let decision = { usePs: false, reason: '', target: 20, query: null };
try {
  const wh = $('Webhook').first().json.body || {};
  const searchId = String(wh.searchId || '');
  const tier = $('Resolve Search Tier').first().json || {};
  const target = Number(tier.minCount) >= 40 ? 40 : 20;
  const ascii = (s) => /^[\x20-\x7e]*$/.test(s);
  // The recruiter's own title when it is plain English. An Arabic title searches by its
  // English translation - the one Google's queries are built from - instead of skipping.
  const rawPosition = String(wh.position || '');
  let titleSource = rawPosition;
  if (!ascii(rawPosition)) {
    try {
      titleSource = String($('Apply Translation').first().json.position || '');
    } catch (e) {
      titleSource = '';
    }
  }
  const location = String(wh.location || '').toLowerCase();
  const title = titleSource
    .replace(/["“”]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase()
    .slice(0, 80)
    .trim();
  const org = String(wh.organizationId || '');
  decision.target = target;

  if (!CONFIG.enabled) decision.reason = 'disabled';
  else if (!searchId) decision.reason = 'no searchId';
  else if (CONFIG.orgAllowlist.length && !CONFIG.orgAllowlist.includes(org)) decision.reason = 'organisation not in the allowlist';
  else if (!IRAQ_WORDS.some((w) => location.includes(w))) decision.reason = 'not an Iraq search';
  else if (!title || !/[a-z]/.test(title) || !ascii(title) || !ascii(titleSource)) decision.reason = 'title is not plain English';
  else {
    decision.usePs = true;
    decision.reason = 'person search first';
    decision.query = {
      country: 'IQ',
      current_role_title: '"' + title + '"',
      enrich_profiles: 'skip',
      page_size: String(target),
    };
    const sd = $getWorkflowStaticData('global');
    const now = Date.now();
    for (const key of ['hhSpend', 'hhPersonSearch', 'hhPsLinks']) {
      sd[key] = sd[key] || {};
      for (const [id, rec] of Object.entries(sd[key])) {
        const at = rec && typeof rec.at === 'number' ? rec.at : 0;
        if (now - at > DAY_MS) delete sd[key][id];
      }
    }
    sd.hhSpend[searchId] = { ceiling: CONFIG.ceiling[target], spent: 0, at: now };
  }
} catch (e) {
  decision = { usePs: false, reason: 'plan error: ' + String((e && e.message) || e).slice(0, 200), target: decision.target, query: null };
}

return [{ json: decision }];

/**
 * Person Search Links - read the Person Search answer and pick the phase-1 route.
 *
 * The request asked for links only (enrich_profiles=skip), as many as the search wants.
 * EnrichLayer bills 3 credits per result returned (measured 2026-10-01: 11 single-result
 * calls cost 33 credits). Results without a usable URL were never seen; they are billed
 * here too, to keep the spend record on the high side.
 *
 *   route 'ps'     - the links alone fill the search (>= 20 / 40): Google's phase 1 is
 *                    skipped; Google stays the phase-2 backup if candidates fall short.
 *   route 'google' - fewer links than the search wants, an error, 403/503 or nothing:
 *                    Google's phase 1 runs exactly as before, and whatever links we did
 *                    get are put in front of Google's (Add Person Search Links).
 *
 * Every link is rewritten to https://www.linkedin.com/in/<slug>: the search already
 * filtered by country=IQ, and Filter New URLs would otherwise drop a two-letter country
 * subdomain (ae., qa. ...) AFTER the route was chosen on it - a 'ps' route left with no
 * profile would end the search with no completion.
 *
 * A request that never got an answer (timeout, network) books the worst case, 3 x the
 * links asked for: EnrichLayer may still have billed it. If the Person Search node failed
 * as a whole, n8n passes this node its INPUT (the plan item): no request went out, nothing
 * is booked, and the reason is recorded. Links are kept in static data for this execution;
 * Add Person Search Links hands them on once and deletes them. This node never throws.
 */
let out = { __psRoute: 'google', links: 0, returned: 0, total: null, status: 0, error: '' };
try {
  const wh = $('Webhook').first().json.body || {};
  const searchId = String(wh.searchId || '');
  const plan = $('Person Search Plan').first().json || {};
  const target = Number(plan.target) >= 40 ? 40 : 20;
  const res = $input.first().json || {};
  const status = Number(res.statusCode || 0);
  const body = res.body && typeof res.body === 'object' ? res.body : {};
  const results = Array.isArray(body.results) ? body.results : null;
  const now = Date.now();
  let error = '';
  let booked = 0;
  if (res.error) {
    error = String(res.error.message || res.error).slice(0, 200);
    booked = 3 * target;
  } else if (!status && Object.prototype.hasOwnProperty.call(res, 'usePs')) {
    error = 'person search node failed (its input was passed on)';
  } else if (status !== 200) {
    error = 'person search answered ' + status;
  }

  const links = [];
  const seen = new Set();
  if (status === 200 && results) {
    for (const r of results) {
      const m = String((r && r.linkedin_profile_url) || '').trim().match(/linkedin\.com\/in\/([^?#/]+)/i);
      if (!m) continue;
      let slug = m[1];
      try { slug = decodeURIComponent(slug); } catch (e) {}
      slug = slug.trim().toLowerCase();
      if (!slug || seen.has(slug)) continue;
      seen.add(slug);
      links.push('https://www.linkedin.com/in/' + m[1]);
    }
    booked = 3 * results.length;
  }
  const returned = status === 200 && results ? results.length : 0;
  const route = links.length >= target ? 'ps' : 'google';
  const total = typeof body.total_result_count === 'number' ? body.total_result_count : null;

  const sd = $getWorkflowStaticData('global');
  if (searchId) {
    if (sd.hhSpend && sd.hhSpend[searchId]) {
      sd.hhSpend[searchId].spent = Number(sd.hhSpend[searchId].spent || 0) + booked;
    }
    sd.hhPsLinks = sd.hhPsLinks || {};
    if (links.length) sd.hhPsLinks[searchId] = { at: now, links };
    else delete sd.hhPsLinks[searchId];
    sd.hhPersonSearch = sd.hhPersonSearch || {};
    sd.hhPersonSearch[searchId] = { at: now, status, total, returned, links: links.length, route, booked, error };
  }
  out = { __psRoute: route, links: links.length, returned, total, status, booked, error };
} catch (e) {
  out = { __psRoute: 'google', links: 0, returned: 0, total: null, status: 0, error: 'links error: ' + String((e && e.message) || e).slice(0, 200) };
}

return [{ json: out }];

/**
 * Add Person Search Links - put the Person Search links in front of the phase-1 list.
 *
 * Sits between Filter LinkedIn URLs and Filter New URLs, and is reached two ways in
 * phase 1 (only one per search):
 *   - from Skip Google? when Person Search filled the search by itself: the input is a
 *     control item, the output is the Person Search links alone;
 *   - from Filter LinkedIn URLs after Google's phase 1: the Person Search links (if any)
 *     go FIRST - they passed our evaluation far more often - then Google's.
 * Each Person Search link is marked __ps so Enrichlayer Profile Fetch asks for the
 * cached profile (use_cache=if-present, 1 credit instead of 2). The links are handed on
 * once and deleted. Phase 2 passes through untouched.
 */
const wh = $('Webhook').first().json.body || {};
const searchId = String(wh.searchId || '');
const sd = $getWorkflowStaticData('global');
const items = $input.all();

if (sd.hhPhase2 && sd.hhPhase2[searchId]) return items;

const isLink = (j) => /linkedin\.com\/in\//i.test(String((j && (j.link || j.url)) || ''));
const rec = sd.hhPsLinks && sd.hhPsLinks[searchId];
const psLinks = rec && Array.isArray(rec.links) ? rec.links : [];
if (sd.hhPsLinks) delete sd.hhPsLinks[searchId];

const fromSearch = psLinks.map((link) => ({ json: { link, __ps: true } }));
return [...fromSearch, ...items.filter((i) => isLink(i.json))];
